class HelpbarFE
{
private:
    enum {
        ARROW_H,
        ARROW_V,
        ARROW_BOTH,
        CROSS,
        TRIANGLE,
        CIRCLE,
        SQUARE,
        BTN_NUM
    };

    char padding[0xB0];
    stringx default_text[BTN_NUM];
    bool disabled;

    void ChangeBtn(int index, bool add, stringx text);

public:
    void Reset();
};

__asm__(".equ __7stringxPCci, 0x0034D438");
__asm__(".equ __7stringxRC7stringx, 0x0034D4D0");
__asm__(".equ _$_7stringx, 0x0034D6E0");
__asm__(".equ ChangeBtn__9HelpbarFEibG7stringx, 0x001BDB10");

void HelpbarFE::Reset()
{
    ChangeBtn(CROSS, true, default_text[CROSS]);
    ChangeBtn(TRIANGLE, true, default_text[TRIANGLE]);
    ChangeBtn(CIRCLE, false, "");
    ChangeBtn(SQUARE, false, "");
    ChangeBtn(ARROW_BOTH, true, default_text[ARROW_BOTH]);
    ChangeBtn(ARROW_H, false, "");
    ChangeBtn(ARROW_V, false, "");
    disabled = false;
}
